window.DOSIK=window.DOSIK||{};DOSIK["sw_community"]={"2":[{"t":"table","title":"한국 새마을운동·지역사회복지의 시작","head":["항목","내용"],"rows":[["새마을운동","기본정신은 근면, 자조, 협동, 정부가 지정한 새마을의 날은 매년 4월 22일 · 새마을운동중앙본부가 창립되어 민간주도로 전환 · 농촌생활환경 개선운동으로 시작한 이 운동은 소득증대운동으로 발전하지 못하였다"],["새마을운동 확대","농촌 새마을운동에서 도시 새마을운동으로 확대"],["향약","주민 교화 등을 목적으로 한 지식인 간의 자치적인 협동조직"],["선교사의 시설","메리 놀스(M. Knowles)에 의해 반열방이 설립 · 태화여자관은 메리 마이어스(M. D. Myers)에 의해 설립"]]},{"t":"table","title":"영국 지역사회복지의 역사","head":["항목","내용"],"rows":[["자선조직협회(COS)","사회진화론에 영향을 받았다"],["토인비홀","사무엘 바네트(S. Barnett) 목사가 설립한 인보관"],["시봄(Seebohm)보고서","사회서비스의 협력과 통합을 제안"],["그리피스 보고서","Griffiths: 지방정부의 책임을 강조"]]}],"3":[{"t":"table","title":"지역사회복지 이론","head":["주제","내용"],"rows":[["권력의 균형적 배분","지역사회조직은 권력의 균형적인 배분을 위해 지역사회자원 개발에 힘써야 한다"],["이해관계의 대립","이해관계의 대립을 불평등한 분배로 설명한다"],["네트워크와 사회적 자본","네트워크는 사회적 자본의 전제가 된다, 지역사회의 집합적 자산으로서 의미를 가진다 · 한 번 형성된 후에도 소멸될 수 있다 · 신뢰는 공동체의 문제를 해결할 수 있는 자원이다"]]}],"4":[{"t":"table","title":"지역사회복지 실천모델","head":["모델","내용"],"rows":[["사회행동모델","주요 기술과 기법은 갈등, 대결, 협상 · 권리가 박탈당한 사람의 이익을 대변한다 · 변화를 위한 기본 전략은 ‘억압자에 대항하기 위한 규합’을 추구"],["사회행동모델(계속)","지역사회 내 불평등한 권력구조의 변화를 지향 · 변화 매개체로 대중조직을 활용 · 여성운동, 빈민운동, 환경운동 등 시민운동에도 활용될 수 있다"],["사회계획모델","사회복지사의 역할은 분석가, 행정가 등"],["지역사회개발모델","변화 매개체는 과업지향적 소집단, 조직화를 위한 구성원의 능력개발에 초점을 둔다 · 일차적 구성원은 지역사회 이웃주민 · 사회복지사의 주요 역할은 조직가, 교육자, 촉진자, 코치"],["변화의 표적체계","지방정부, 외부개발자, 지역주민을 변화의 표적체계로 본다"]]}],"5":[{"t":"table","title":"지역사회복지 실천과정","head":["단계","내용"],"rows":[["실천과정","지역사회문제 해결과정으로 볼 수 있다"],["사정","지역사회 사정은 지역사회의 욕구와 자원을 파악하는 단계 · 지역사회 문제나 욕구는 지역사회 상황에 따라 다양한 형태로 나타날 수 있다"],["계획","구체적인 실행계획 단계에서는 정책 접근법, 프로그램 접근법, 프로젝트 접근법 등을 사용한다"],["실행","자원동원, 재정집행, 네트워크는 실행단계에서 수행된다"]]}],"6":[{"t":"table","title":"조직화·네트워크·연계기술","head":["기술","내용"],"rows":[["네트워크","지역사회 구성원간 신뢰와 호혜성이 형성되면 네트워크가 지속될 수 있다"],["조직화","효과적인 주민 조직화를 위해 주민의 개인적 이익에 대한 관심을 조직화에 활용할 수 있다"],["임파워먼트","개인의 문제와 제도적 권력관계의 연관성을 깨닫도록 하는 노력이 중요하다"],["사회자본","사회자본을 만들기 위해 지역주민들이 서로에 대한 책임감을 인식하도록 돕는다"],["연계기술의 효과","클라이언트 중심의 사회적 관계망을 강화시킬 수 있다 · 이용자 중심의 통합적 서비스를 제공할 수 있다 · 새로운 인프라 구축에 필요한 시간과 비용을 줄일 수 있다 · 사회복지시설의 서비스 중복ㆍ누락을 방지할 수 있다"]]},{"t":"tree","title":"옹호기술","root":"옹호","branches":[["개인 옹호","주민 스스로 자신을 옹호하기 어려운 상황에서 그 개인과 가족을 대신하여 수행하는 활동"],["집단 옹호","특정 집단이 불이익을 받을 때 이들의 공동 문제를 해결하기 위한 활동"],["정치 옹호","입법, 행정, 사법영역에서 다양한 형태로 전개되는 사회 정의와 복지 증진을 위한 활동"],["체계변화 옹호","지역주민들과 함께 근본적인 제도상의 변화를 도모하는 활동"]]}],"7":[{"t":"table","title":"지역사회보장계획·협의체","head":["항목","내용"],"rows":[["지역사회보장계획","지역사회보장협의체 심의를 거쳐 지방의회에 보고한다 · 수립 및 지역사회보장조사의 시기ㆍ방법 등에 필요한 사항은 대통령령으로 정한다"],["실무협의체","위원은 10명 이상 40명 이하로 구성한다"]]},{"t":"vs","title":"지방분권과 지역복지","cols":[{"name":"특징","items":["우리나라는 지방자치법의 제정으로 도입되었다","지역복지 실현을 위해 중앙정부와 분담적 관계를 추구한다","사회복지서비스의 책임과 권한이 지방에 이양된다","지역사회복지에 대한 자기통치 원리가 중요시된다"]},{"name":"장점","items":["지역복지 활성화의 토대가 될 수 있다","지역주민의 의사를 반영한 행정서비스가 강화된다","주민참여로 권력의 재분배가 이루어진다"]},{"name":"한계","items":["지역 간의 경쟁이 심화되어 지역 이기주의가 나타날 수 있다","지역 간 상대적 박탈감으로 사회적 형평성 문제가 발생된다"]}]}],"8":[{"t":"table","title":"사회복지협의회·사회복지공동모금회","head":["기관","내용"],"rows":[["사회복지협의회","시ㆍ도 사회복지협의회는 한국사회복지협의회의 지회로 운영된다 · 사회복지에 관한 조사ㆍ연구 및 정책을 건의한다"],["사회복지협의회(계속)","사회복지 관련 기관ㆍ단체 간의 연계ㆍ협력ㆍ조정 등을 수행한다 · 시ㆍ도 및 시ㆍ군ㆍ구 단위에도 의무 설치한다"],["사회복지공동모금회","사회복지법인이다 · 특별시ㆍ광역시ㆍ특별자치시ㆍ도ㆍ특별자치도 단위 사회복지공동모금지회를 둔다"],["모금회 명칭·복권","모금회가 아닌 자는 사회복지공동모금 또는 이와 유사한 명칭을 사용하지 못한다 · 사회복지활동 등을 지원하기 위한 재원을 조성하기 위하여 복권을 발행할 수 있다"]]},{"t":"table","title":"사회적 경제","head":["기업","내용"],"rows":[["마을기업","운영 원칙은 공동체성, 공공성, 지역성, 기업성"],["자활기업","「협동조합 기본법」에 따라 자활공동체에서 명칭이 변경되었다"],["사회적기업","취약계층에게 사회서비스 또는 일자리를 제공한다"],["사회적 경제","이윤 극대화의 시장경제와 달리 사람의 가치를 우위에 두는 경제활동"]]}],"9":[{"t":"table","title":"지역사회복지운동","head":["항목","내용"],"rows":[["성격","목적지향적인 조직적 활동 · 지역사회복지운동에는 다양한 이념이 사용될 수 있다"],["목표와 활동","지역사회의 부당한 권력구조를 변화시키기 위해 노력한다 · 지역주민 참여를 위한 수요자 중심의 활동이 이루어진다"],["목표와 활동(계속)","지역사회의 다양한 자원 활용 및 조직 간 유기적 협력이 이루어진다 · 복지권리ㆍ시민의식을 배양하는 사회권 확립운동"],["주된 관심사","주민 삶의 질과 관련된 생활영역에 있다"],["주체","사회복지 실무자도 포함되며, 사회복지전문가, 지역활동가, 지역사회복지이용자 등 다양하다"],["예","조례제정운동과 같은 제도변화과정을 예로 들 수 있다"]]}]};
