(window.TNQ=window.TNQ||[]).push({"terms":{"반열방":{"d":"선교사 메리 놀스가 세운 한국 최초의 사회복지 시설 가운데 하나입니다.","r":["태화여자관"]},"태화여자관":{"d":"선교사 메리 마이어스가 설립한 사회복지관의 시초 격인 시설입니다.","r":["반열방"]},"사회적 자본":{"d":"신뢰와 네트워크처럼 협력을 가능하게 하는 공동체의 무형 자산입니다.","r":["네트워크"]},"네트워크":{"d":"사람이나 조직이 서로 연결된 관계망으로 사회적 자본의 전제가 됩니다.","r":["사회적 자본"]},"표적체계":{"d":"변화를 일으키려고 영향을 주어야 하는 대상 체계입니다.","r":[]},"사회자본":{"d":"구성원 사이의 신뢰와 호혜성 같은 사회적 관계에서 생기는 자원입니다.","r":["사회적 자본"]}},"notes":{"Griffiths: 지방정부의 책임을 강조":"그리피스 보고서는 지역사회돌봄에서 지방정부가 맡을 책임을 강조했습니다.","「협동조합 기본법」에 따라 자활공동체에서 명칭이 변경되었다":"자활기업은 협동조합 기본법에 따라 자활공동체라는 명칭이 바뀐 것입니다.","개인의 문제와 제도적 권력관계의 연관성을 깨닫도록 하는 노력이 중요하다":"임파워먼트에서는 개인의 문제가 제도와 권력관계에서 비롯됨을 깨닫도록 돕는 노력이 핵심입니다.","구체적인 실행계획 단계에서는 정책 접근법, 프로그램 접근법, 프로젝트 접근법 등을 사용한다":"계획 단계에서 구체적인 실행계획을 세울 때는 정책, 프로그램, 프로젝트 접근법을 씁니다.","권리가 박탈당한 사람의 이익을 대변한다":"사회행동모델은 권리를 빼앗긴 사람들의 이익을 대신해 목소리를 냅니다.","기본정신은 근면, 자조, 협동, 정부가 지정한 새마을의 날은 매년 4월 22일":"새마을운동은 근면, 자조, 협동을 기본정신으로 하며 새마을의 날은 정부가 매년 4월 22일로 정했습니다.","네트워크는 사회적 자본의 전제가 된다, 지역사회의 집합적 자산으로서 의미를 가진다":"네트워크는 사회적 자본이 생기는 전제이고 지역사회가 함께 가진 자산이라는 의미가 있습니다.","농촌 새마을운동에서 도시 새마을운동으로 확대":"새마을운동은 농촌에서 시작해 도시 새마을운동으로 영역을 넓혔습니다.","농촌생활환경 개선운동으로 시작한 이 운동은 소득증대운동으로 발전하지 못하였다":"농촌생활환경 개선운동으로 출발한 새마을운동은 소득증대운동으로까지 발전하지 못했다는 설명은 틀립니다.","메리 놀스(M. Knowles)에 의해 반열방이 설립":"메리 놀스가 선교사로서 세운 시설이 반열방입니다.","모금회가 아닌 자는 사회복지공동모금 또는 이와 유사한 명칭을 사용하지 못한다":"모금회가 아닌 곳은 사회복지공동모금 같은 이름이나 비슷한 이름을 쓸 수 없습니다.","변화를 위한 기본 전략은 ‘억압자에 대항하기 위한 규합’을 추구":"사회행동모델의 변화 전략은 억압하는 쪽에 맞서려고 힘을 모으는 규합입니다.","변화 매개체는 과업지향적 소집단, 조직화를 위한 구성원의 능력개발에 초점을 둔다":"개발모델은 과업지향적 소집단을 변화 매개체로 삼고 조직화를 위해 구성원의 능력 개발에 초점을 둡니다.","변화 매개체로 대중조직을 활용":"사회행동모델은 대중조직을 변화의 수단으로 삼습니다.","복지권리ㆍ시민의식을 배양하는 사회권 확립운동":"복지권리와 시민의식을 키우는 사회권 확립운동도 지역사회복지운동의 활동입니다.","사무엘 바네트(S. Barnett) 목사가 설립한 인보관":"토인비홀은 사무엘 바네트 목사가 세운 영국의 인보관입니다.","사회복지 관련 기관ㆍ단체 간의 연계ㆍ협력ㆍ조정 등을 수행한다":"협의회는 사회복지 관련 기관과 단체 사이의 연계, 협력, 조정을 맡습니다.","사회복지사의 역할은 분석가, 행정가 등":"사회계획모델에서 사회복지사는 분석가나 행정가 역할을 합니다.","사회복지사의 주요 역할은 조직가, 교육자, 촉진자, 코치":"개발모델에서 사회복지사는 조직가, 교육자, 촉진자, 코치로 일합니다.","사회복지서비스의 책임과 권한이 지방에 이양된다":"지방분권이 이루어지면 사회복지서비스의 책임과 권한이 지방으로 넘어갑니다.","사회복지시설의 서비스 중복ㆍ누락을 방지할 수 있다":"연계기술은 시설들의 서비스가 겹치거나 빠지는 일을 막아 줍니다.","사회복지 실무자도 포함되며, 사회복지전문가, 지역활동가, 지역사회복지이용자 등 다양하다":"운동의 주체에는 사회복지 실무자뿐 아니라 전문가, 지역활동가, 이용자도 포함됩니다.","사회복지에 관한 조사ㆍ연구 및 정책을 건의한다":"사회복지협의회는 사회복지에 관한 조사와 연구를 하고 정책을 건의합니다.","사회복지활동 등을 지원하기 위한 재원을 조성하기 위하여 복권을 발행할 수 있다":"공동모금회는 사회복지활동 지원 재원을 만들려고 복권을 발행할 수 있습니다.","사회서비스의 협력과 통합을 제안":"시봄보고서는 영국에서 사회서비스를 서로 협력하고 통합하자고 제안한 보고서입니다.","사회자본을 만들기 위해 지역주민들이 서로에 대한 책임감을 인식하도록 돕는다":"사회자본을 만들려면 주민들이 서로에게 책임감을 갖도록 돕습니다.","새로운 인프라 구축에 필요한 시간과 비용을 줄일 수 있다":"연계기술로 새 인프라를 만드는 데 드는 시간과 비용을 아낄 수 있습니다.","새마을운동중앙본부가 창립되어 민간주도로 전환":"새마을운동중앙본부가 창립되면서 운동의 주도권이 정부에서 민간으로 넘어갔습니다.","수립 및 지역사회보장조사의 시기ㆍ방법 등에 필요한 사항은 대통령령으로 정한다":"보장계획의 수립 방식과 지역사회보장조사를 언제 어떻게 할지는 대통령령이 정합니다.","시ㆍ도 및 시ㆍ군ㆍ구 단위에도 의무 설치한다":"협의회는 시ㆍ도뿐 아니라 시ㆍ군ㆍ구 단위에도 법에 따라 의무적으로 설치합니다.","시ㆍ도 사회복지협의회는 한국사회복지협의회의 지회로 운영된다":"시ㆍ도의 협의회는 독립 기관이 아니라 한국사회복지협의회의 지회로서 운영됩니다.","신뢰는 공동체의 문제를 해결할 수 있는 자원이다":"신뢰는 공동체가 겪는 문제를 풀어 갈 수 있는 자원이 됩니다.","여성운동, 빈민운동, 환경운동 등 시민운동에도 활용될 수 있다":"여성운동, 빈민운동, 환경운동 같은 시민운동에도 이 모델을 쓸 수 있습니다.","우리나라는 지방자치법의 제정으로 도입되었다":"우리나라의 지방자치는 지방자치법이 제정되면서 도입되었습니다.","운영 원칙은 공동체성, 공공성, 지역성, 기업성":"마을기업은 공동체성, 공공성, 지역성, 기업성을 운영 원칙으로 합니다.","위원은 10명 이상 40명 이하로 구성한다":"실무협의체는 위원 10명 이상 40명 이하로 구성합니다.","이용자 중심의 통합적 서비스를 제공할 수 있다":"연계기술로 이용자 중심의 통합적 서비스를 줄 수 있습니다.","이윤 극대화의 시장경제와 달리 사람의 가치를 우위에 두는 경제활동":"사회적 경제는 이윤 극대화가 목적인 시장경제와 달리 사람의 가치를 앞세우는 경제활동입니다.","이해관계의 대립을 불평등한 분배로 설명한다":"갈등이론에서는 이해관계가 맞서는 까닭을 자원이 불평등하게 분배되기 때문이라고 설명합니다.","일차적 구성원은 지역사회 이웃주민":"개발모델이 일차적으로 상대하는 구성원은 그 동네의 이웃주민입니다.","입법, 행정, 사법영역에서 다양한 형태로 전개되는 사회 정의와 복지 증진을 위한 활동":"정치 옹호는 입법, 행정, 사법 영역에서 사회 정의와 복지 증진을 위해 벌이는 활동입니다.","자원동원, 재정집행, 네트워크는 실행단계에서 수행된다":"실행 단계에서는 자원을 동원하고 재정을 집행하며 네트워크를 운영합니다.","조례제정운동과 같은 제도변화과정을 예로 들 수 있다":"조례제정운동처럼 제도를 바꾸어 가는 과정이 지역사회복지운동의 예입니다.","주민 교화 등을 목적으로 한 지식인 간의 자치적인 협동조직":"향약은 지식인들이 주민을 교화하려고 만든 자치적 협동조직입니다.","주민 삶의 질과 관련된 생활영역에 있다":"지역사회복지운동의 주된 관심사는 주민의 삶의 질과 관련된 생활영역입니다.","주민 스스로 자신을 옹호하기 어려운 상황에서 그 개인과 가족을 대신하여 수행하는 활동":"개인 옹호는 스스로 옹호하기 어려운 주민의 개인과 가족을 대신해 하는 활동입니다.","주민참여로 권력의 재분배가 이루어진다":"주민이 참여하면서 권력이 더 고르게 나뉘는 재분배가 이뤄집니다.","주요 기술과 기법은 갈등, 대결, 협상":"사회행동모델은 갈등, 대결, 협상이라는 기술과 기법을 주로 씁니다.","지방정부, 외부개발자, 지역주민을 변화의 표적체계로 본다":"실천모델에서 변화의 표적체계는 지방정부와 외부개발자, 지역주민입니다.","지역 간 상대적 박탈감으로 사회적 형평성 문제가 발생된다":"지역 간 상대적 박탈감이 생겨 사회적 형평성 문제가 나타납니다.","지역 간의 경쟁이 심화되어 지역 이기주의가 나타날 수 있다":"지방분권의 한계로 지역 간 경쟁이 심해져 지역 이기주의가 생길 수 있습니다.","지역복지 실현을 위해 중앙정부와 분담적 관계를 추구한다":"지역복지를 이루려고 지방은 중앙정부와 역할을 나누어 맡는 관계를 추구합니다.","지역복지 활성화의 토대가 될 수 있다":"지방분권은 지역복지가 활기를 띠는 토대가 될 수 있습니다.","지역사회 구성원간 신뢰와 호혜성이 형성되면 네트워크가 지속될 수 있다":"구성원 사이에 신뢰와 호혜성이 생기면 네트워크가 오래 이어질 수 있습니다.","지역사회 내 불평등한 권력구조의 변화를 지향":"사회행동모델은 지역사회의 불평등한 권력구조를 바꾸려 합니다.","지역사회 문제나 욕구는 지역사회 상황에 따라 다양한 형태로 나타날 수 있다":"문제나 욕구는 그 지역이 처한 상황에 따라 여러 모습으로 나타날 수 있습니다.","지역사회문제 해결과정으로 볼 수 있다":"실천은 문제를 하나씩 풀어 가는 과정으로 볼 수 있습니다.","지역사회보장협의체 심의를 거쳐 지방의회에 보고한다":"지역사회보장계획은 지역사회보장협의체가 심의한 뒤 지방의회에 보고합니다.","지역사회복지에 대한 자기통치 원리가 중요시된다":"지방분권에서는 지역이 스스로 다스리는 자기통치 원리가 중요시됩니다.","지역사회복지운동에는 다양한 이념이 사용될 수 있다":"복지운동은 하나의 이념에 갇히지 않고 다양한 이념을 쓸 수 있습니다.","지역사회 사정은 지역사회의 욕구와 자원을 파악하는 단계":"사정은 그 지역의 욕구가 무엇이고 쓸 수 있는 자원이 무엇인지 파악하는 단계입니다.","지역사회의 다양한 자원 활용 및 조직 간 유기적 협력이 이루어진다":"지역사회복지운동은 지역의 다양한 자원을 활용하고 조직 사이의 협력을 유기적으로 이룹니다.","지역사회의 부당한 권력구조를 변화시키기 위해 노력한다":"복지운동은 지역의 부당한 권력구조를 바꾸려고 노력합니다.","지역사회조직은 권력의 균형적인 배분을 위해 지역사회자원 개발에 힘써야 한다":"권력의 균형적 배분을 위해 지역사회조직은 자원을 개발하는 데 힘써야 한다는 입장입니다.","지역주민들과 함께 근본적인 제도상의 변화를 도모하는 활동":"체계변화 옹호는 지역주민과 함께 제도 자체의 근본적인 변화를 꾀하는 활동입니다.","지역주민의 의사를 반영한 행정서비스가 강화된다":"지방분권으로 주민 의사를 반영한 행정서비스가 강해집니다.","지역주민 참여를 위한 수요자 중심의 활동이 이루어진다":"지역사회복지운동은 수요자를 중심에 두고 주민 참여를 이끄는 활동을 합니다.","취약계층에게 사회서비스 또는 일자리를 제공한다":"사회적기업은 취약계층에게 사회서비스나 일자리를 제공하는 기업입니다.","클라이언트 중심의 사회적 관계망을 강화시킬 수 있다":"연계기술은 클라이언트를 중심에 둔 사회적 관계망을 튼튼하게 합니다.","태화여자관은 메리 마이어스(M. D. Myers)에 의해 설립":"태화여자관은 선교사 메리 마이어스가 설립한 시설입니다.","특별시ㆍ광역시ㆍ특별자치시ㆍ도ㆍ특별자치도 단위 사회복지공동모금지회를 둔다":"공동모금회는 특별시, 광역시, 도 등 단위로 지회를 둡니다.","특정 집단이 불이익을 받을 때 이들의 공동 문제를 해결하기 위한 활동":"집단 옹호는 특정 집단이 불이익을 받을 때 그 집단의 공동 문제를 풀기 위한 활동입니다.","한 번 형성된 후에도 소멸될 수 있다":"네트워크는 한번 만들어졌더라도 관리하지 않으면 사라질 수 있습니다.","효과적인 주민 조직화를 위해 주민의 개인적 이익에 대한 관심을 조직화에 활용할 수 있다":"주민 조직화를 효과적으로 하려면 주민 개인의 이익에 대한 관심을 이용할 수 있습니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
